    "src/lib/storage/Liquidator.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

library Liquidator {
    bytes32 constant _SLOT_PATH = keccak256(abi.encode("xyz.meridian.Liquidator.Data"));

    struct Data {
        /// Full position liquidated takeovers are transferred in the liquidatorAccount
        address account;
        /// The subaccount identifier for the address holding the liquidated positions
        bytes32 subaccount;
        /// Accumulated balance delta across multiple deleverage actions for the current deleverage sequence.
        int256 deleverageBalanceDelta;
        /// The message index that initiated the current deleverage sequence.
        /// Non-zero while a deleverage sequence is in progress. All subsequent
        /// deleverage actions in the same sequence must share this index.
        uint64 deleverageMessageIdx;
        /// Current quote token being deleveraged.
        address deleverageQuoteToken;
    }

    function load() internal pure returns (Data storage $) {
        bytes32 s = _SLOT_PATH;
        assembly {
            $.slot := s
        }
    }
}
"
    },
    "src/lib/storage/PerpPosition.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

library PerpPosition {
    struct Data {
        /// Position size; positive is long/buy and negative is short/sell, zero is closed
        int128 size;
        /// Current position cost, zero when closed
        uint128 cost;
        /// The cumulative funding at the point of matched orders
        int128 lastFundingUsd;
        /// The cumulative position fee at the point of matched orders or explicit realization
        uint128 lastPositionFeeUsd;
    }

    /// @dev Updates an existing perp position struct with new perp position values.
    function update(PerpPosition.Data storage self, PerpPosition.Data memory position) internal {
        self.size = position.size;
        self.cost = position.cost;
        self.lastFundingUsd = position.lastFundingUsd;
        self.lastPositionFeeUsd = position.lastPositionFeeUsd;
    }

    /// @dev Clears a perp position struct to zero values.
    function clear(PerpPosition.Data storage self) internal {
        self.size = 0;
        self.cost = 0;
        self.lastFundingUsd = 0;
        self.lastPositionFeeUsd = 0;
    }
}
"
    },
    "src/lib/storage/PerpProduct.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {IPerpEngine} from "../../interface/IPerpEngine.sol";
import {ProductStatus} from "../../share/Enums.sol";
import {PerpPosition} from "./PerpPosition.sol";

library PerpProduct {
    struct Data {
        /// Mapping of account/subaccount to position
        mapping(address account => mapping(bytes32 subaccount => PerpPosition.Data)) positions;
        /// Mapping of digest to filled order quantity
        mapping(bytes32 digest => uint128 amount) filled;
        /// Generated unique identifier
        uint32 id;
        /// The fee schedule for the maker and taker fees
        uint32 feeScheduleId;
        /// Trading restriction status of the product
        ProductStatus status;
        /// Maximum allowed leverage, only whole numbers
        uint16 maxLeverage;
        /// Pyth price feedId.
        uint32 pythFeedId;
        /// Total funding accumulated (USD terms) per unit of size (native)
        int128 cumulativeFundingUsd;
        /// Bytes32 name of the base token name (e.g. ETH in ETHUSD)
        bytes32 baseTokenName;
        /// Bytes32 name of the quote token name (e.g. USD in ETHUSD)
        bytes32 quoteTokenName;
        /// Maximum quantity size per order (multiple of lotSize)
        uint128 maxQuantity;
        /// Smallest quantity size per order (set once on registration)
        uint128 lotSize;
        /// Minimum product tick size (e.g. 0.01)
        uint128 tickSize;
        /// Total product OI in native units (e.g. 5 short, 5 long then 5 OI)
        uint128 openInterest;
        /// Maximum open interest allowed for the product (quote units, D9)
        uint128 maxOpenInterestUsd;
        /// Maximum position notional value allowed per product (quote units, D9)
        uint128 maxPositionNotionalUsd;
        /// Pyth-verified settlement price (gwei, 1e9) recorded at delist finalization
        uint128 delistExpiryPrice;
        /// True once delisting has been initiated (before terminal DELISTED status)
        bool delistInvoked;
        /// Engine expiry message index every force-settlement and the finalize for this delist must share
        uint64 delistMessageIdx;
        /// Total position fee accumulated (USD terms) per unit of size (native)
        uint128 cumulativePositionFeeUsd;
    }

    /// @dev Info is the Data that can be stored in memory
    struct Info {
        uint32 id;
        uint32 feeScheduleId;
        ProductStatus status;
        uint16 maxLeverage;
        uint32 pythFeedId;
        int128 cumulativeFundingUsd;
        bytes32 baseTokenName;
        bytes32 quoteTokenName;
        uint128 maxQuantity;
        uint128 tickSize;
        uint128 lotSize;
        uint128 openInterest;
        uint128 maxOpenInterestUsd;
        uint128 maxPositionNotionalUsd;
        uint128 delistExpiryPrice;
        bool delistInvoked;
        uint64 delistMessageIdx;
        uint128 cumulativePositionFeeUsd;
    }

    function load(uint32 productId) internal pure returns (PerpProduct.Data storage $) {
        bytes32 s = keccak256(abi.encode("xyz.meridian.PerpProduct.Data", productId));
        assembly {
            $.slot := s
        }
    }

    function loadPendingUpdate(uint32 productId) internal pure returns (IPerpEngine.UpdatePerpProductParams storage $) {
        bytes32 s = keccak256(abi.encode("xyz.meridian.PerpProduct.PendingUpdate", productId));
        assembly {
            $.slot := s
        }
    }
}
"
    },
    "src/lib/storage/ProductRegistry.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {EngineType} from "../../share/Enums.sol";

library ProductRegistry {
    bytes32 constant _SLOT_PATH = keccak256(abi.encode("xyz.meridian.ProductRegistry.Data"));

    struct Data {
        /// Last used productId from prior register invocation
        uint32 productIdCounter;
        /// Mapping of tickers by engineType
        mapping(EngineType engineType => mapping(bytes ticker => bool used)) usedTickers;
    }

    function load() internal pure returns (Data storage $) {
        bytes32 s = _SLOT_PATH;
        assembly {
            $.slot := s
        }
    }

    /// @dev Returns the next productId for the given engineType then updating id counter.
    function getAndIncrementNextProductId(ProductRegistry.Data storage self) internal returns (uint32) {
        uint32 nextId = self.productIdCounter + 1;
        self.productIdCounter = nextId;
        return nextId;
    }
}
"
    },
    "src/lib/storage/Token.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

library Token {
    struct Data {
        /// Bytes32 name of the token
        bytes32 name;
        /// ERC20 address, synthetic accounting key, or zero for virtual tokens.
        address tokenAddress;
        /// Whether concrete-token deposits are enabled.
        bool depositEnabled;
        /// Whether concrete-token withdrawals are enabled.
        bool withdrawEnabled;
        /// If the token is used by a product (as either a quote or base asset), it cannot ever be removed.
        bool removeProtected;
        /// Concrete-token capacity in D9, including pending deposits and excluding initiated withdrawals.
        uint256 depositCapacity;
        /// Minimum concrete-token deposit in D9.
        uint256 minDeposit;
        /// Flat concrete-token withdrawal fee in D9.
        uint128 withdrawFee;
        /// Flat concrete-token deposit fee in D9.
        uint128 depositFee;
        /// Address of the OFT contract (or OFTAdapter)
        address oftAddress;
        /// Concrete backing token; nonzero only for synthetic tokens.
        address backingToken;
    }

    function load(bytes32 name) internal pure returns (Data storage $) {
        bytes32 s = keccak256(abi.encode("xyz.meridian.Token.Data", name));
        assembly {
            $.slot := s
        }
    }

    /// @dev Resets a token back to its zero default state.
    function remove(Token.Data storage self) internal {
        self.name = bytes32(0);
        self.tokenAddress = address(0);
        self.depositCapacity = 0;
        self.minDeposit = 0;
        self.withdrawFee = 0;
        self.depositFee = 0;
        self.depositEnabled = false;
        self.withdrawEnabled = false;
        self.removeProtected = false;
        self.oftAddress = address(0);
        self.backingToken = address(0);
    }
}
"
